<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\DcrInitialAccessToken\Domain\ValueObject\Accessor\DcrInitialAccessTokenAllowedGrantTypesAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the DcrInitialAccessTokenAllowedGrantTypesAccessor trait.
 *
 * Covers null default, string/VO assignment via withAllowedGrantTypes,
 * getAllowedGrantTypes/allowedGrantTypes accessors, and isAllowedGrantTypesChanged with/without original.
 */
class DcrInitialAccessTokenAllowedGrantTypesAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withAllowedGrantTypes creates a new instance with the AllowedGrantTypes set
     * from a string value, and getAllowedGrantTypes returns the primitive string.
     */
    public function testWithAllowedGrantTypesFromString(): void
    {
        // Arrange
        $holder = new ImplWithDcrInitialAccessTokenAllowedGrantTypesAccessorUnitTest();

        // Act
        $result = $holder->withAllowedGrantTypes('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getAllowedGrantTypes());
    }
    /**
     * Asserts that withallowedGrantTypes has access to the value object
     * from a string value, and getAllowedGrantTypes returns the primitive string.
     */
    public function testWithAllowedGrantTypesFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithDcrInitialAccessTokenAllowedGrantTypesAccessorUnitTest();

        // Act
        $result = $holder->withAllowedGrantTypes('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->allowedGrantTypes()->value());
    }
    public function testChangedAllowedGrantTypes(): void
    {
        // Arrange
        $holder = new ImplWithDcrInitialAccessTokenAllowedGrantTypesAccessorUnitTest();
        $original = $holder->withAllowedGrantTypes('one');
        $same = $holder->withAllowedGrantTypes('one');
        $modified = $holder->withAllowedGrantTypes('other');

        // Act
        $unchanged = $holder->isAllowedGrantTypesChanged();
        $withSame = $original->isAllowedGrantTypesChanged($same);
        $withDiferent = $original->isAllowedGrantTypesChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithDcrInitialAccessTokenAllowedGrantTypesAccessorUnitTest
{
    use DcrInitialAccessTokenAllowedGrantTypesAccessor;
}
